        /* Floating point registers */

        for (i = 0; i < 32; ++i) {

            if (env->CP0_Status & (1 << CP0St_FR)) {

                err = kvm_mips_get_one_ureg64(cs, KVM_REG_MIPS_FPR_64(i),

