        if (pc->packet_index + buf_size <= pc->packet_len) {

            memcpy(pc->packet + pc->packet_index, buf, buf_size);

            pc->packet_index += buf_size;

            if (pc->packet_index >= pc->packet_len) {

                *poutbuf = pc->packet;

                *poutbuf_size = pc->packet_len;

                pc->packet_index = 0;

                return buf_size;

            }

        } else {

            /* erroneous size */

            pc->packet_index = 0;

        }

    }

    *poutbuf = NULL;

    *poutbuf_size = 0;

    return buf_size;

}


